questions_list = []
qid = 1
for cat, q_list in categories_data.items():
    for title, tips, keywords, ideal_points in q_list:
        difficulty = "Medium"
        if any(w in title.lower() for w in ["basic", "what is", "difference between"]):
            difficulty = "Easy"
        elif any(w in title.lower() for w in ["architecture", "design", "internals", "system", "deadlock"]):
            difficulty = "Hard"
            
        company = ["Google", "Amazon", "Microsoft", "Meta", "Uber", "Oracle", "Flipkart", "Infosys", "TCS"][qid % 9]
        role = "Software Engineer"
        if cat in ["DBMS", "SQL"]:
            role = "Database Engineer"
        elif cat == "Frontend":
            role = "Frontend Engineer"
        elif cat == "Backend":
            role = "Backend Engineer"
        elif cat == "Python":
            role = "Python Developer"
        elif cat == "Java":
            role = "Java Developer"
        elif cat == "Git":
            role = "DevOps Engineer"
            
        questions_list.append({
            "id": qid,
            "category": cat,
            "role": role,
            "difficulty": difficulty,
            "title": title,
            "tips": tips,
            "keywords": keywords,
            "ideal_points": ideal_points,
            "company": company
        })
        qid += 1

